const input=$json??{};
const dealId=input.deal_id??null; const leadId=input.lead_id??null; const propertyId=input.property_id??null;
const status=String(input.status??'').toLowerCase(); const action=String(input.action??'').toLowerCase();
const dnc=Boolean(input.dnc??input.do_not_contact??false); const blockers=Array.isArray(input.blockers)?input.blockers:[];
const attempts=Number(input.reengagement_attempts??input.attempts??0); const maxAttempts=Number(input.max_reengagement_attempts??3);
const seller=input.seller??{}; const phone=String(seller.phone??input.seller_phone??'').trim(); const email=String(seller.email??input.seller_email??'').trim();
const cadence=String(input.cadence??(attempts<=0?'24h':attempts===1?'72h':'7d'));
const context=input.seller_context??input.motivation??input.conversation_context??null;
let route='human_review'; let messageMode='none'; let reason='Re-engagement message requires review.'; let nextWorkflow='WF-126';
if(dnc){route='blocked';reason='DNC protection prevents outbound communication.';nextWorkflow='WF-126';}
else if(blockers.length){route='blocked';reason='Active blocker prevents outbound communication.';nextWorkflow='WF-126';}
else if(!dealId||!leadId||!propertyId||(!phone&&!email)){route='incomplete';reason='Deal identity or seller contact is missing.';nextWorkflow='WF-345';}
else if(attempts>=maxAttempts){route='human_review';reason='Maximum re-engagement attempts reached.';nextWorkflow='WF-126';}
else if(status==='reengagement_ready'||action==='schedule_reengagement'){route='message_ready';messageMode=phone?'sms': 'email';reason='Controlled re-engagement message may be generated and dispatched.';nextWorkflow='WF-262';}
else{route='human_review';reason='WF-346 received an outcome not authorized for autonomous re-engagement.';nextWorkflow='WF-345';}
const idempotencyKey='WF-346:'+String(dealId??'unknown')+':reengagement:'+String(attempts+1)+':'+cadence;
const activity={activity_type:'seller_reengagement_message_controller',subject:'WF-346 '+(dealId??'unknown-deal'),deal_id:dealId,lead_id:leadId,property_id:propertyId,status,action,route,message_mode:messageMode,cadence,reengagement_attempts:attempts,next_attempt:attempts+1,max_reengagement_attempts:maxAttempts,recipient_phone:phone,recipient_email:email,seller_context:context,dnc,blockers,idempotency_key:idempotencyKey,reason,next_workflow:nextWorkflow};
return [{json:{...input,wf_id:'WF-346',route,message_mode:messageMode,cadence,reengagement_attempts:attempts,next_reengagement_attempt:attempts+1,idempotency_key:idempotencyKey,next_workflow:nextWorkflow,reason,crm_activity:activity,evaluated_at:new Date().toISOString()}}];
